  "Prepared by our restaurant team for private events, office lunches, family gatherings and local celebrations.":
    { es:"Preparado por el equipo de nuestro restaurante para eventos privados, almuerzos de oficina, reuniones familiares y celebraciones locales.",
      it:"Preparato dal team del nostro ristorante per eventi privati, pranzi aziendali, riunioni di famiglia e celebrazioni locali.",
      pt:"Preparado pela equipe do nosso restaurante para eventos privados, almoços de empresa, encontros de família e celebrações locais." },
  "Request Catering Quote": { es:"Solicitar Presupuesto de Catering", it:"Richiedi Preventivo Catering", pt:"Solicitar Orçamento de Catering" },
  "Serving Pompano Beach, Fort Lauderdale and nearby communities.": { es:"Atendemos Pompano Beach, Fort Lauderdale y comunidades cercanas.", it:"Serviamo Pompano Beach, Fort Lauderdale e le comunità vicine.", pt:"Atendemos Pompano Beach, Fort Lauderdale e comunidades próximas." },
  "Service styles": { es:"Tipos de servicio", it:"Tipi di servizio", pt:"Tipos de serviço" },
  "Choose how we <em>cater</em>": { es:"Elige cómo <em>servimos</em>", it:"Scegli come <em>serviamo</em>", pt:"Escolha como <em>atendemos</em>" },
  "Bring our kitchen to your venue with a fully-equipped truck experience.": { es:"Lleva nuestra cocina a tu lugar con una experiencia de food truck totalmente equipado.", it:"Porta la nostra cucina nel tuo spazio con un'esperienza di food truck completamente attrezzato.", pt:"Leve nossa cozinha ao seu local com uma experiência de food truck totalmente equipado." },
  "Private Chef On-Site": { es:"Chef Privado en el Lugar", it:"Chef Privato sul Posto", pt:"Chef Privado no Local" },
  "Our chef cooks live at your event — pizza station, pasta bar, fresh focaccia.": { es:"Nuestro chef cocina en vivo en tu evento — estación de pizza, barra de pasta, focaccia fresca.", it:"Il nostro chef cucina dal vivo al tuo evento — postazione pizza, pasta bar, focaccia fresca.", pt:"Nosso chef cozinha ao vivo no seu evento — estação de pizza, bar de massas, focaccia fresca." },
  "Drop-off Catering": { es:"Catering con Entrega", it:"Catering con Consegna", pt:"Catering com Entrega" },
  "Trays, platters and dessert boxes delivered to your location.": { es:"Bandejas, fuentes y cajas de postres entregadas en tu ubicación.", it:"Vassoi, taglieri e box di dolci consegnati alla tua sede.", pt:"Bandejas, travessas e caixas de sobremesa entregues no seu local." },
  "Not sure yet": { es:"Aún no estoy seguro", it:"Non ancora sicuro", pt:"Ainda não tenho certeza" },
  "Tell us about your event and we’ll match the right format.": { es:"Cuéntanos sobre tu evento y encontraremos el formato adecuado.", it:"Raccontaci del tuo evento e troveremo il formato giusto.", pt:"Conte-nos sobre o seu evento e encontramos o formato certo." },
  "Tell us about your <em>event</em>": { es:"Cuéntanos sobre tu <em>evento</em>", it:"Raccontaci del tuo <em>evento</em>", pt:"Conte-nos sobre o seu <em>evento</em>" },
  "Share a few event details so our team can recommend the right setup, staffing and service style.":
    { es:"Comparte algunos detalles del evento para que nuestro equipo pueda recomendarte la configuración, el personal y el tipo de servicio adecuados.",
      it:"Condividi alcuni dettagli dell'evento così il nostro team potrà consigliarti l'allestimento, il personale e il tipo di servizio giusti.",
      pt:"Compartilhe alguns detalhes do evento para que nossa equipe recomende a estrutura, a equipe e o tipo de serviço ideais." },
